mapper.update:
UPDATE budget
SET used_amount = used_amount + #{amount},
    updated_at  = NOW()
WHERE tenant_id   = #{tenantId}
  AND dept_id     = #{deptId}
  AND period      = #{period}
  AND deleted     = 0
  AND used_amount + #{amount} <= total_budget

UPDATE budget
SET used_amount = GREATEST(used_amount - #{amount}, 0),
    updated_at  = NOW()
WHERE tenant_id = #{tenantId}
  AND dept_id   = #{deptId}
  AND period    = #{period}
  AND deleted   = 0

mapper.select:
SELECT id, tenant_id, dept_name, dept_id, period, total_budget, used_amount
FROM budget
WHERE tenant_id = #{tenantId}
  AND dept_id   = #{deptId}
  AND period    = #{period}
  AND deleted   = 0
LIMIT 1
